-- Atomic order creation. Runs security invoker so RLS still applies per-caller —
-- a cashier cannot be tricked into cross-branch inserts even through this function.
-- print_station is resolved here from menu_items/categories, never trusted from the client.

create or replace function create_order(
  p_branch_id uuid,
  p_order_type order_type,
  p_payment_method payment_method,
  p_items jsonb,       -- [{menu_item_id, variant_id, quantity, notes}, ...]
  p_notes text default null
) returns uuid
language plpgsql security invoker as $$
declare
  v_order_id uuid;
  v_item jsonb;
  v_variant record;
  v_subtotal numeric(12,2) := 0;
  v_tax_rate numeric(5,4);
  v_line_total numeric(12,2);
  v_item_count int := 0;
begin
  if p_branch_id <> auth_branch_id() and not is_super_admin() then
    raise exception 'branch mismatch';
  end if;

  if jsonb_array_length(p_items) = 0 then
    raise exception 'order must contain at least one item';
  end if;

  select coalesce(tax_rate, 0) into v_tax_rate
  from receipt_settings where branch_id = p_branch_id;

  insert into orders (branch_id, cashier_id, order_number, order_type, payment_method, notes)
  values (p_branch_id, auth.uid(), 'TEMP', p_order_type, p_payment_method, p_notes)
  returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items) loop
    select miv.price, mi.name as item_name, miv.name as variant_name,
           coalesce(mi.print_station, c.default_print_station) as print_station
      into v_variant
      from menu_item_variants miv
      join menu_items mi on mi.id = miv.menu_item_id
      join categories c on c.id = mi.category_id
      where miv.id = (v_item->>'variant_id')::uuid
        and mi.id = (v_item->>'menu_item_id')::uuid
        and miv.is_active and mi.is_active;

    if not found then
      raise exception 'invalid or inactive menu item/variant: %', v_item;
    end if;

    v_line_total := v_variant.price * (v_item->>'quantity')::int;
    v_subtotal := v_subtotal + v_line_total;
    v_item_count := v_item_count + 1;

    insert into order_items (
      order_id, branch_id, menu_item_id, variant_id, item_name, variant_name,
      unit_price, quantity, line_total, print_station, notes
    )
    values (
      v_order_id, p_branch_id, (v_item->>'menu_item_id')::uuid, (v_item->>'variant_id')::uuid,
      v_variant.item_name, v_variant.variant_name, v_variant.price,
      (v_item->>'quantity')::int, v_line_total, v_variant.print_station,
      v_item->>'notes'
    );
  end loop;

  update orders set
    order_number = 'ORD-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval('order_seq')::text, 4, '0'),
    subtotal = v_subtotal,
    tax_amount = round(v_subtotal * v_tax_rate, 2),
    total_amount = v_subtotal + round(v_subtotal * v_tax_rate, 2)
  where id = v_order_id;

  return v_order_id;
end;
$$;

revoke execute on function create_order(uuid, order_type, payment_method, jsonb, text) from public;
grant execute on function create_order(uuid, order_type, payment_method, jsonb, text) to authenticated;

-- Legitimate order voiding — SUPER_ADMIN only, always attributed and reasoned.
-- Reports must always show voided orders as a distinct visible line, never exclude them.
create or replace function void_order(p_order_id uuid, p_reason text)
returns void
language plpgsql security invoker as $$
begin
  if not is_super_admin() then
    raise exception 'only SUPER_ADMIN can void an order';
  end if;

  if p_reason is null or length(trim(p_reason)) = 0 then
    raise exception 'a void reason is required';
  end if;

  update orders
  set status = 'VOID', voided_at = now(), voided_by = auth.uid(), void_reason = p_reason
  where id = p_order_id;

  if not found then
    raise exception 'order not found: %', p_order_id;
  end if;
end;
$$;

revoke execute on function void_order(uuid, text) from public;
grant execute on function void_order(uuid, text) to authenticated;

