2	export type CookieOptions = Partial<SerializeOptions>;
3	export type CookieOptionsWithName = {
4	    name?: string;
5	} & CookieOptions;
6	export type GetCookie = (name: string) => Promise<string | null | undefined> | string | null | undefined;
7	export type SetCookie = (name: string, value: string, options: CookieOptions) => Promise<void> | void;
8	export type RemoveCookie = (name: string, options: CookieOptions) => Promise<void> | void;
