17	    name: string;
18	    value: string;
19	    options: CookieOptions;
20	}[], 
21	/**
22	 * Headers that must be set on the HTTP response alongside the cookies.
23	 * Responses that set auth cookies must not be cached by CDNs or
24	 * reverse proxies, otherwise one user's session token can be served
25	 * to a different user.
26	 *
27	 * The library passes the following headers when auth cookies are set:
28	 * - `Cache-Control: private, no-cache, no-store, must-revalidate, max-age=0`
29	 * - `Expires: 0`
30	 * - `Pragma: no-cache`
31	 *
32	 * @example
33	 * ```ts
34	 * // Next.js middleware
35	 * setAll(cookiesToSet, headers) {
36	 *   cookiesToSet.forEach(({ name, value, options }) =>
37	 *     response.cookies.set(name, value, options)
38	 *   )
39	 *   Object.entries(headers).forEach(([key, value]) =>
40	 *     response.headers.set(key, value)
41	 *   )
42	 * }
43	 * ```
44	 */
45	headers: Record<string, string>) => Promise<void> | void;
46	export type CookieMethodsBrowserDeprecated = {
47	    get: GetCookie;
