import { NextResponse, type NextRequest } from 'next/server'
import { createServerClient } from '@supabase/ssr'
import type { AppClaims } from '@/lib/auth/roles'

// Next.js 16 renamed the `middleware.ts` convention to `proxy.ts` (see
// node_modules/next/dist/docs/01-app/02-guides/upgrading/version-16.md).
// This is UX-only route redirection — RLS (supabase/migrations/0002_rls_policies.sql)
// is the actual security boundary if Supabase is ever hit directly.

const PUBLIC_EXACT = ['/', '/login']
const PUBLIC_PREFIXES = ['/menu', '/branches', '/contact', '/auth']

function isPublicPath(pathname: string) {
  if (PUBLIC_EXACT.includes(pathname)) return true
  return PUBLIC_PREFIXES.some((p) => pathname === p || pathname.startsWith(p + '/'))
}

export async function proxy(request: NextRequest) {
  let response = NextResponse.next({ request })

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value))
          response = NextResponse.next({ request })
          cookiesToSet.forEach(({ name, value, options }) =>
            response.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  const { data } = await supabase.auth.getClaims()
  const claims = data?.claims as AppClaims | undefined
  const path = request.nextUrl.pathname

  if (!claims) {
    if (isPublicPath(path)) return response
    return NextResponse.redirect(new URL('/login', request.url))
  }

  const role = claims.user_role

  if (path === '/login') {
    return NextResponse.redirect(new URL(role === 'SUPER_ADMIN' ? '/admin' : '/pos', request.url))
  }
  if (path.startsWith('/admin') && role !== 'SUPER_ADMIN') {
    return NextResponse.redirect(new URL('/pos', request.url))
  }
  if (path.startsWith('/pos') && role !== 'CASHIER' && role !== 'SUPER_ADMIN') {
    return NextResponse.redirect(new URL('/login', request.url))
  }

  return response
}

export const config = {
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|webp|ico)$).*)',
  ],
}

