'use server'

import { revalidatePath } from 'next/cache'
import { createClient } from '@/lib/supabase/server'

function readBranchFields(formData: FormData) {
  const name = String(formData.get('name') ?? '').trim()
  const address = String(formData.get('address') ?? '').trim() || null
  const phone = String(formData.get('phone') ?? '').trim() || null
  if (!name) throw new Error('Nama cabang wajib diisi')
  return { name, address, phone }
}

export async function createBranch(formData: FormData) {
  const supabase = await createClient()
  const fields = readBranchFields(formData)

  const { error } = await supabase.from('branches').insert(fields)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/branches')
}

export async function updateBranch(id: string, formData: FormData) {
  const supabase = await createClient()
  const fields = readBranchFields(formData)

  const { error } = await supabase.from('branches').update(fields).eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/branches')
}

export async function setBranchActive(id: string, isActive: boolean) {
  const supabase = await createClient()
  const { error } = await supabase.from('branches').update({ is_active: isActive }).eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/branches')
}

