'use server'

import { revalidatePath } from 'next/cache'
import { createClient } from '@/lib/supabase/server'
import type { PrintStation } from '@/lib/supabase/types'

function readPrintStation(formData: FormData, field = 'default_print_station'): PrintStation {
  const v = String(formData.get(field) ?? 'KITCHEN')
  if (v === 'KITCHEN' || v === 'BAR' || v === 'NONE') return v
  return 'KITCHEN'
}

// ===== Categories =====
export async function createCategory(formData: FormData) {
  const supabase = await createClient()
  const name = String(formData.get('name') ?? '').trim()
  if (!name) throw new Error('Nama kategori wajib diisi')

  const { error } = await supabase.from('categories').insert({
    name,
    default_print_station: readPrintStation(formData),
  })
  if (error) throw new Error(error.message)
  revalidatePath('/admin/menu')
}

export async function updateCategory(id: string, formData: FormData) {
  const supabase = await createClient()
  const name = String(formData.get('name') ?? '').trim()
  if (!name) throw new Error('Nama kategori wajib diisi')

  const { error } = await supabase
    .from('categories')
    .update({ name, default_print_station: readPrintStation(formData) })
    .eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/menu')
}

export async function setCategoryActive(id: string, isActive: boolean) {
  const supabase = await createClient()
  const { error } = await supabase.from('categories').update({ is_active: isActive }).eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/menu')
}

// ===== Menu items =====
export async function createMenuItem(categoryId: string, formData: FormData) {
  const supabase = await createClient()
  const name = String(formData.get('name') ?? '').trim()
  const description = String(formData.get('description') ?? '').trim() || null
  const overrideRaw = String(formData.get('print_station') ?? '')
  const print_station = overrideRaw ? readPrintStation(formData, 'print_station') : null
  if (!name) throw new Error('Nama menu wajib diisi')

  const { error } = await supabase.from('menu_items').insert({
    category_id: categoryId,
    name,
    description,
    print_station,
  })
  if (error) throw new Error(error.message)
  revalidatePath('/admin/menu')
}

export async function updateMenuItem(id: string, formData: FormData) {
  const supabase = await createClient()
  const name = String(formData.get('name') ?? '').trim()
  const description = String(formData.get('description') ?? '').trim() || null
  const overrideRaw = String(formData.get('print_station') ?? '')
  const print_station = overrideRaw ? readPrintStation(formData, 'print_station') : null
  if (!name) throw new Error('Nama menu wajib diisi')

  const { error } = await supabase
    .from('menu_items')
    .update({ name, description, print_station })
    .eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/menu')
}

export async function setMenuItemActive(id: string, isActive: boolean) {
  const supabase = await createClient()
  const { error } = await supabase.from('menu_items').update({ is_active: isActive }).eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/menu')
}

// ===== Variants =====
export async function createVariant(menuItemId: string, formData: FormData) {
  const supabase = await createClient()
  const name = String(formData.get('name') ?? '').trim()
  const price = Number(formData.get('price'))
  const isDefault = formData.get('is_default') === 'on'
  if (!name) throw new Error('Nama varian wajib diisi')
  if (!Number.isFinite(price) || price < 0) throw new Error('Harga tidak valid')

  const { error } = await supabase.from('menu_item_variants').insert({
    menu_item_id: menuItemId,
    name,
    price,
    is_default: isDefault,
  })
  if (error) throw new Error(error.message)
  revalidatePath('/admin/menu')
}

export async function setVariantActive(id: string, isActive: boolean) {
  const supabase = await createClient()
  const { error } = await supabase
    .from('menu_item_variants')
    .update({ is_active: isActive })
    .eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/menu')
}

