'use client'

import { useState, useTransition } from 'react'
import {
  Dialog,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Badge } from '@/components/ui/badge'
import { createVariant, setVariantActive } from '@/app/admin/menu/actions'

interface Variant {
  id: string
  name: string
  price: number
  is_default: boolean
  is_active: boolean
}

interface VariantManagerDialogProps {
  trigger: React.ReactElement
  menuItemName: string
  menuItemId: string
  variants: Variant[]
}

export function VariantManagerDialog({ trigger, menuItemName, menuItemId, variants }: VariantManagerDialogProps) {
  const [error, setError] = useState<string | null>(null)
  const [isPending, startTransition] = useTransition()

  function handleAdd(formData: FormData) {
    setError(null)
    startTransition(async () => {
      try {
        await createVariant(menuItemId, formData)
      } catch (e) {
        setError(e instanceof Error ? e.message : 'Terjadi kesalahan')
      }
    })
  }

  return (
    <Dialog>
      <DialogTrigger render={trigger} />
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Varian — {menuItemName}</DialogTitle>
        </DialogHeader>

        <div className="space-y-2">
          {variants.length ? (
            variants.map((v) => (
              <div key={v.id} className="flex items-center justify-between rounded-md border px-3 py-2 text-sm">
                <span>
                  {v.name}
                  {v.is_default ? <Badge variant="secondary" className="ml-2">Default</Badge> : null}
                  <span className="ml-2 text-muted-foreground">Rp{v.price.toLocaleString('id-ID')}</span>
                </span>
                <form action={setVariantActive.bind(null, v.id, !v.is_active)}>
                  <Button type="submit" variant="outline" size="sm">
                    {v.is_active ? 'Nonaktifkan' : 'Aktifkan'}
                  </Button>
                </form>
              </div>
            ))
          ) : (
            <p className="text-sm text-muted-foreground">Belum ada varian.</p>
          )}
        </div>

        <form action={handleAdd} className="flex items-end gap-2 border-t pt-3">
          <div className="flex-1 space-y-1">
            <Label htmlFor="v-name">Nama Varian</Label>
            <Input id="v-name" name="name" placeholder="Regular" required />
          </div>
          <div className="w-28 space-y-1">
            <Label htmlFor="v-price">Harga</Label>
            <Input id="v-price" name="price" type="number" min={0} step={100} required />
          </div>
          <label className="flex items-center gap-1 pb-2 text-xs text-muted-foreground">
            <input type="checkbox" name="is_default" className="size-3.5" />
            Default
          </label>
          <Button type="submit" disabled={isPending}>
            {isPending ? '...' : 'Tambah'}
          </Button>
        </form>
        {error ? <p className="text-sm text-destructive">{error}</p> : null}
      </DialogContent>
    </Dialog>
  )
}

