      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Varian — {menuItemName}</DialogTitle>
        </DialogHeader>

        <div className="space-y-2">
          {variants.length ? (
            variants.map((v) => (
              <div key={v.id} className="flex items-center justify-between rounded-md border px-3 py-2 text-sm">
                <span>
                  {v.name}
                  {v.is_default ? <Badge variant="secondary" className="ml-2">Default</Badge> : null}
                  <span className="ml-2 text-muted-foreground">Rp{v.price.toLocaleString('id-ID')}</span>
                </span>
