                  <Button type="submit" variant="outline" size="sm">
                    {v.is_active ? 'Nonaktifkan' : 'Aktifkan'}
                  </Button>
                </form>
              </div>
            ))
          ) : (
            <p className="text-sm text-muted-foreground">Belum ada varian.</p>
