            <Label htmlFor="v-name">Nama Varian</Label>
            <Input id="v-name" name="name" placeholder="Regular" required />
          </div>
          <div className="w-28 space-y-1">
            <Label htmlFor="v-price">Harga</Label>
            <Input id="v-price" name="price" type="number" min={0} step={100} required />
          </div>
          <label className="flex items-center gap-1 pb-2 text-xs text-muted-foreground">
            <input type="checkbox" name="is_default" className="size-3.5" />
