import { create } from 'zustand'
import type { PrintStation } from '@/lib/supabase/types'

export interface CartLine {
  lineId: string
  menuItemId: string
  variantId: string
  itemName: string
  variantName: string
  unitPrice: number
  quantity: number
  printStation: PrintStation
  notes?: string
}

export type OrderTypeValue = 'DINE_IN' | 'TAKEAWAY'
export type PaymentMethodValue = 'CASH' | 'QRIS'

interface CartState {
  branchId: string | null
  orderType: OrderTypeValue
  paymentMethod: PaymentMethodValue | null
  lines: CartLine[]

  setBranchId: (branchId: string | null) => void
  addItem: (line: Omit<CartLine, 'lineId'>) => void
  updateQuantity: (lineId: string, quantity: number) => void
  removeItem: (lineId: string) => void
  setOrderType: (orderType: OrderTypeValue) => void
  setPaymentMethod: (paymentMethod: PaymentMethodValue) => void
  clear: () => void
}

// Intentionally in-memory only (no persist middleware) — a stale cart reappearing
// after a shift change or register reload is a real bug class we want to avoid.
export const useCartStore = create<CartState>((set) => ({
  branchId: null,
  orderType: 'DINE_IN',
  paymentMethod: null,
  lines: [],

  setBranchId: (branchId) => set({ branchId }),

  addItem: (line) =>
    set((s) => {
      const existing = s.lines.find((l) => l.variantId === line.variantId && !line.notes && !l.notes)
      if (existing) {
        return {
          lines: s.lines.map((l) =>
            l.lineId === existing.lineId ? { ...l, quantity: l.quantity + line.quantity } : l
          ),
        }
      }
      return { lines: [...s.lines, { ...line, lineId: crypto.randomUUID() }] }
    }),

  updateQuantity: (lineId, quantity) =>
    set((s) => ({
      lines:
        quantity <= 0
          ? s.lines.filter((l) => l.lineId !== lineId)
          : s.lines.map((l) => (l.lineId === lineId ? { ...l, quantity } : l)),
    })),

  removeItem: (lineId) => set((s) => ({ lines: s.lines.filter((l) => l.lineId !== lineId) })),
  setOrderType: (orderType) => set({ orderType }),
  setPaymentMethod: (paymentMethod) => set({ paymentMethod }),
  clear: () => set({ lines: [], paymentMethod: null }),
}))

export function cartSubtotal(lines: CartLine[]) {
  return lines.reduce((sum, l) => sum + l.unitPrice * l.quantity, 0)
}

