'use client'

import { useEffect } from 'react'
import { useCartStore } from '@/lib/pos/cart-store'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'

interface BranchGateProps {
  role: 'SUPER_ADMIN' | 'CASHIER'
  fixedBranchId: string | null
  branches: { id: string; name: string }[]
  children: React.ReactNode
}

export function BranchGate({ role, fixedBranchId, branches, children }: BranchGateProps) {
  const branchId = useCartStore((s) => s.branchId)
  const setBranchId = useCartStore((s) => s.setBranchId)

  useEffect(() => {
    if (role === 'CASHIER' && fixedBranchId) setBranchId(fixedBranchId)
  }, [role, fixedBranchId, setBranchId])

  if (role === 'CASHIER') return <>{children}</>

  if (!branchId) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <Card className="w-full max-w-sm">
          <CardHeader>
            <CardTitle>Pilih Cabang</CardTitle>
          </CardHeader>
          <CardContent>
            <Select onValueChange={(v) => setBranchId(v)}>
              <SelectTrigger className="w-full">
                <SelectValue placeholder="Pilih cabang untuk memulai" />
              </SelectTrigger>
              <SelectContent>
                {branches.map((b) => (
                  <SelectItem key={b.id} value={b.id}>
                    {b.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </CardContent>
        </Card>
      </div>
    )
  }

  return <>{children}</>
}

