import { useState } from 'react'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Card, CardContent } from '@/components/ui/card'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { useCartStore } from '@/lib/pos/cart-store'
import type { PrintStation } from '@/lib/supabase/types'

interface Variant {
  id: string
  name: string
  price: number
}

interface MenuItem {
  id: string
  name: string
  description: string | null
  printStation: PrintStation
  variants: Variant[]
}

interface Category {
  id: string
  name: string
  items: MenuItem[]
}

export function MenuGrid({ categories }: { categories: Category[] }) {
  const addItem = useCartStore((s) => s.addItem)
  const [pickerItem, setPickerItem] = useState<MenuItem | null>(null)

  function addVariant(item: MenuItem, variant: Variant) {
    addItem({
      menuItemId: item.id,
      variantId: variant.id,
      itemName: item.name,
      variantName: variant.name,
      unitPrice: variant.price,
      quantity: 1,
      printStation: item.printStation,
    })
  }

  function handlePick(item: MenuItem) {
    if (item.variants.length === 1) {
      addVariant(item, item.variants[0])
      return
