'use client'

import { useEffect, useMemo, useState } from 'react'
import { useRouter } from 'next/navigation'
import { Minus, Plus, Trash2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Separator } from '@/components/ui/separator'
import { cartSubtotal, useCartStore } from '@/lib/pos/cart-store'
import { submitOrder } from '@/lib/pos/order-actions'
import { createClient } from '@/lib/supabase/client'

function formatRp(n: number) {
  return 'Rp' + Math.round(n).toLocaleString('id-ID')
}

export function CartPanel() {
  const router = useRouter()
  const branchId = useCartStore((s) => s.branchId)
  const lines = useCartStore((s) => s.lines)
  const orderType = useCartStore((s) => s.orderType)
  const paymentMethod = useCartStore((s) => s.paymentMethod)
  const updateQuantity = useCartStore((s) => s.updateQuantity)
  const removeItem = useCartStore((s) => s.removeItem)
  const setOrderType = useCartStore((s) => s.setOrderType)
  const setPaymentMethod = useCartStore((s) => s.setPaymentMethod)
  const clear = useCartStore((s) => s.clear)

  const [cashReceived, setCashReceived] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [isSubmitting, setIsSubmitting] = useState(false)

  const subtotal = useMemo(() => cartSubtotal(lines), [lines])
  const tax = subtotal * taxRate
  const total = subtotal + tax
  const change = paymentMethod === 'CASH' && cashReceived ? Number(cashReceived) - total : null

  const canSubmit = !!branchId && lines.length > 0 && !!paymentMethod && !isSubmitting

  async function handleSubmit() {
    if (!branchId || !paymentMethod) return
    setError(null)
    setIsSubmitting(true)
    try {
      const orderId = await submitOrder({ branchId, orderType, paymentMethod, lines })
      clear()
      router.push(`/pos/receipt/${orderId}`)
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Gagal menyimpan pesanan')
      setIsSubmitting(false)
    }
  }

  return (
    <div className="flex h-full flex-col gap-3">
      <div className="flex gap-2">
        <Button
          type="button"
          variant={orderType === 'DINE_IN' ? 'default' : 'outline'}
          className="flex-1"
          onClick={() => setOrderType('DINE_IN')}
        >
          Dine-in
        </Button>
        <Button
          type="button"
          variant={orderType === 'TAKEAWAY' ? 'default' : 'outline'}
          className="flex-1"
          onClick={() => setOrderType('TAKEAWAY')}
        >
          Takeaway
        </Button>
      </div>

      <div className="flex-1 space-y-2 overflow-y-auto">
        {lines.map((line) => (
          <div key={line.lineId} className="flex items-center justify-between gap-2 rounded-md border p-2 text-sm">
            <div className="min-w-0 flex-1">
              <p className="truncate font-medium">{line.itemName}</p>
              <p className="text-xs text-muted-foreground">
                {line.variantName} · {formatRp(line.unitPrice)}
              </p>
            </div>
            <div className="flex items-center gap-1">
              <Button
                type="button"
                variant="outline"
                size="icon-sm"
                onClick={() => updateQuantity(line.lineId, line.quantity - 1)}
              >
                <Minus className="size-3" />
              </Button>
              <span className="w-6 text-center">{line.quantity}</span>
              <Button
                type="button"
                variant="outline"
                size="icon-sm"
                onClick={() => updateQuantity(line.lineId, line.quantity + 1)}
              >
                <Plus className="size-3" />
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="icon-sm"
                onClick={() => removeItem(line.lineId)}
              >
                <Trash2 className="size-3.5 text-destructive" />
