import { createClient } from '@/lib/supabase/server'
import { MenuGrid } from '@/components/pos/menu-grid'
import { CartPanel } from '@/components/pos/cart-panel'

export default async function PosPage() {
  const supabase = await createClient()
  const [{ data: categories }, { data: items }, { data: variants }] = await Promise.all([
    supabase.from('categories').select('*').eq('is_active', true).order('sort_order'),
    supabase.from('menu_items').select('*').eq('is_active', true).order('sort_order'),
    supabase.from('menu_item_variants').select('*').eq('is_active', true).order('sort_order'),
  ])

  const variantsByItem = new Map<string, typeof variants>()
  for (const v of variants ?? []) {
    const list = variantsByItem.get(v.menu_item_id) ?? []
    list.push(v)
    variantsByItem.set(v.menu_item_id, list)
  }

  const itemsByCategory = new Map<
    string,
    { id: string; name: string; description: string | null; printStation: string; variants: typeof variants }[]
  >()
  for (const item of items ?? []) {
    const list = itemsByCategory.get(item.category_id) ?? []
    list.push({
      id: item.id,
      name: item.name,
      description: item.description,
      printStation: (item.print_station ??
        categories?.find((c) => c.id === item.category_id)?.default_print_station ??
        'KITCHEN') as string,
      variants: variantsByItem.get(item.id) ?? [],
    })
    itemsByCategory.set(item.category_id, list)
  }

  const menu = (categories ?? [])
    .map((c) => ({
      id: c.id,
      name: c.name,
      items: (itemsByCategory.get(c.id) ?? []).filter((i) => i.variants.length > 0),
    }))
    .filter((c) => c.items.length > 0)

  return (
    <div className="grid h-[calc(100vh-6rem)] grid-cols-1 gap-4 lg:grid-cols-[1fr_360px]">
      <div className="overflow-y-auto">
        <MenuGrid categories={menu as never} />
      </div>
      <div className="rounded-lg border p-3">
        <CartPanel />
      </div>
    </div>
  )
}

