/* Thermal receipt print styles — 58mm/80mm paper widths.
   Isolates the .receipt-print subtree during printing (classic print-only pattern) so the
   POS chrome (header, buttons, dialogs) never leaks onto paper. */

.receipt-print {
  font-family: 'Courier New', Courier, monospace;
  font-size: 12px;
  line-height: 1.4;
}

.receipt-print.paper-58mm {
  width: 48mm;
}

.receipt-print.paper-80mm {
  width: 72mm;
}

@media print {
  @page {
    margin: 0;
  }

  body * {
    visibility: hidden;
  }

  .receipt-print,
  .receipt-print * {
    visibility: visible;
  }

  .receipt-print {
    position: absolute;
    top: 0;
    left: 0;
    margin: 0;
    padding: 2mm;
  }

  .no-print {
    display: none !important;
  }
}

