// Minimal ESC/POS byte builder shared by the LAN print-agent (Node, raw TCP) and the
// browser Bluetooth client — both paths must emit identical byte sequences.

function bytesToBase64(bytes: Uint8Array): string {
  if (typeof Buffer !== 'undefined') return Buffer.from(bytes).toString('base64')
  let binary = ''
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i])
  return btoa(binary)
}

export type Align = 'left' | 'center' | 'right'

export class EscPosBuilder {
  private chunks: number[] = []

  /** ESC @ — initialize printer state */
  init(): this {
    this.chunks.push(0x1b, 0x40)
    return this
  }

  bold(on: boolean): this {
    this.chunks.push(0x1b, 0x45, on ? 1 : 0)
    return this
  }

  align(mode: Align): this {
    const n = mode === 'left' ? 0 : mode === 'center' ? 1 : 2
    this.chunks.push(0x1b, 0x61, n)
    return this
  }

  /** GS ! n — double width/height, w/h each 1 (normal) or 2 (double) */
  textSize(w: 1 | 2, h: 1 | 2): this {
    const n = ((w - 1) << 4) | (h - 1)
    this.chunks.push(0x1d, 0x21, n)
    return this
  }

  text(s: string): this {
    this.chunks.push(...Array.from(new TextEncoder().encode(s)))
    return this
  }

  line(s = ''): this {
    return this.text(s + '\n')
  }

  /** ESC d n — feed n lines */
  feed(lines = 1): this {
    this.chunks.push(0x1b, 0x64, lines)
    return this
  }

  /** GS V n — cut (partial by default so the last line stays attached) */
  cut(partial = true): this {
    this.chunks.push(0x1d, 0x56, partial ? 1 : 0)
    return this
  }

  toBytes(): Uint8Array {
    return new Uint8Array(this.chunks)
  }

  toBase64(): string {
    return bytesToBase64(this.toBytes())
  }
}

