'use server'

import { revalidatePath } from 'next/cache'
import { createClient } from '@/lib/supabase/server'
import type { PrintStation } from '@/lib/supabase/types'

function readStation(formData: FormData): PrintStation {
  const v = String(formData.get('station') ?? 'KITCHEN')
  return v === 'BAR' ? 'BAR' : 'KITCHEN'
}

export async function createPrinter(formData: FormData) {
  const supabase = await createClient()
  const branch_id = String(formData.get('branch_id') ?? '')
  const name = String(formData.get('name') ?? '').trim()
  const ip_address = String(formData.get('ip_address') ?? '').trim()
  const port = Number(formData.get('port') ?? 9100)

  if (!branch_id) throw new Error('Cabang wajib dipilih')
  if (!name) throw new Error('Nama printer wajib diisi')
  if (!ip_address) throw new Error('Alamat IP wajib diisi')
  if (!Number.isInteger(port) || port <= 0 || port > 65535) throw new Error('Port tidak valid')

  const { error } = await supabase.from('printers').insert({
    branch_id,
    name,
    ip_address,
    port,
    station: readStation(formData),
  })
  if (error) throw new Error(error.message)
  revalidatePath('/admin/printers')
}

export async function setPrinterActive(id: string, isActive: boolean) {
  const supabase = await createClient()
  const { error } = await supabase.from('printers').update({ is_active: isActive }).eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/printers')
}

