import { createClient } from '@/lib/supabase/client'
import { getPrinterForStation } from './printer-discovery'
import { printViaAgent, type PrintAgentResult } from '@/lib/print/agent-client'
import { buildStationTicket } from '@/lib/print/receipt-templates'
import type { OrderTypeValue } from './cart-store'

function bytesToBase64(bytes: Uint8Array): string {
  let binary = ''
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i])
  return btoa(binary)
}

const STATION_LABEL: Record<'KITCHEN' | 'BAR', string> = {
  KITCHEN: 'DAPUR',
  BAR: 'BAR',
}

export interface StationPrintOutcome {
  station: 'KITCHEN' | 'BAR'
  status: 'printed' | 'no_printer_configured' | 'failed'
  result?: PrintAgentResult
}

// Re-fetches order_items from the DB (source of truth for print_station, resolved
// server-side by create_order) rather than trusting the client cart's station hint.
export async function printKitchenBarTickets(params: {
  orderId: string
  branchId: string
  orderNumber: string
  orderType: OrderTypeValue
}): Promise<StationPrintOutcome[]> {
  const supabase = createClient()
  const { data: items } = await supabase
    .from('order_items')
    .select('item_name, variant_name, quantity, notes, print_station')
    .eq('order_id', params.orderId)

  const stations = (['KITCHEN', 'BAR'] as const).map((station) => ({
    station,
    items: (items ?? []).filter((i) => i.print_station === station),
  }))

  const outcomes: StationPrintOutcome[] = []

  for (const { station, items: stationItems } of stations) {
    if (!stationItems.length) continue

    const printer = await getPrinterForStation(params.branchId, station)
    if (!printer) {
      outcomes.push({ station, status: 'no_printer_configured' })
      continue
    }

    const bytes = buildStationTicket({
      stationLabel: STATION_LABEL[station],
      orderNumber: params.orderNumber,
      orderType: params.orderType,
      items: stationItems.map((i) => ({
        itemName: i.item_name,
        variantName: i.variant_name,
        quantity: i.quantity,
        notes: i.notes ?? undefined,
      })),
    })

    const result = await printViaAgent(printer.ip_address, printer.port, bytesToBase64(bytes))
    outcomes.push({ station, status: result.ok ? 'printed' : 'failed', result })
  }

  return outcomes
}

