'use client'

import { useEffect, useState } from 'react'
import { RefreshCw } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { printKitchenBarTickets, type StationPrintOutcome } from '@/lib/pos/print-order'
import type { OrderTypeValue } from '@/lib/pos/cart-store'

const STATUS_LABEL: Record<StationPrintOutcome['status'], string> = {
  printed: 'Tercetak',
  no_printer_configured: 'Printer belum diatur',
  failed: 'Gagal — printer tidak terjangkau',
}

export function StationPrintButtons(props: {
  branchId: string
  orderId: string
  orderNumber: string
  orderType: OrderTypeValue
}) {
  const [outcomes, setOutcomes] = useState<StationPrintOutcome[] | null>(null)
  const [isPrinting, setIsPrinting] = useState(false)

  async function runPrint() {
    setIsPrinting(true)
    try {
      const result = await printKitchenBarTickets(props)
      setOutcomes(result)
    } finally {
      setIsPrinting(false)
    }
  }

  // Attempt once automatically right after the order is created.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => {
    runPrint()
  }, [props.orderId])

  return (
    <div className="no-print space-y-2 rounded-md border p-3">
      <div className="flex items-center justify-between">
        <p className="text-sm font-medium">Tiket Dapur/Bar</p>
        <Button variant="outline" size="sm" onClick={runPrint} disabled={isPrinting} className="gap-1.5">
          <RefreshCw className="size-3.5" />
          {isPrinting ? 'Mencetak...' : 'Cetak Ulang'}
        </Button>
      </div>
      {outcomes?.length ? (
        <ul className="space-y-1 text-sm">
          {outcomes.map((o) => (
            <li key={o.station} className="flex items-center justify-between">
              <span>{o.station === 'KITCHEN' ? 'Dapur' : 'Bar'}</span>
              <Badge variant={o.status === 'printed' ? 'default' : 'secondary'}>
                {STATUS_LABEL[o.status]}
              </Badge>
            </li>
          ))}
        </ul>
      ) : (
        <p className="text-sm text-muted-foreground">
          {isPrinting ? 'Mengirim tiket...' : 'Tidak ada item untuk dapur/bar.'}
        </p>
      )}
    </div>
  )
}

