// Web Bluetooth is Chrome/Edge only, requires HTTPS (or localhost), and requestDevice()
// requires a user gesture. Service/characteristic UUIDs below match the common thermal
// printer BLE serial profile used by most cheap ESC/POS printers — confirm against your
// specific printer model's datasheet if prints come out garbled or don't arrive at all.
const PRINTER_SERVICE_UUID = '000018f0-0000-1000-8000-00805f9b34fb'
const PRINTER_CHARACTERISTIC_UUID = '00002af1-0000-1000-8000-00805f9b34fb'

// Conservative default BLE ATT MTU payload (23-byte MTU minus 3 bytes protocol overhead).
// Some printers negotiate a larger MTU, but there's no reliable cross-device way to query
// the negotiated value from the Web Bluetooth API, so we stick to the universal floor.
const CHUNK_SIZE = 20
const CHUNK_DELAY_MS = 20

export function isBluetoothSupported(): boolean {
  return typeof navigator !== 'undefined' && 'bluetooth' in navigator
}

export async function pairPrinter(): Promise<BluetoothDevice> {
  const device = await navigator.bluetooth.requestDevice({
    filters: [{ services: [PRINTER_SERVICE_UUID] }],
    optionalServices: [PRINTER_SERVICE_UUID],
  })
  return device
}

// Chrome remembers granted Bluetooth device permissions per-origin natively and exposes
// previously-granted devices via getDevices() — no new picker prompt needed to reconnect.
export async function getRememberedPrinter(): Promise<BluetoothDevice | null> {
  if (!isBluetoothSupported() || !navigator.bluetooth.getDevices) return null
  const devices = await navigator.bluetooth.getDevices()
  return devices[0] ?? null
}

export async function printViaBluetooth(device: BluetoothDevice, bytes: Uint8Array): Promise<void> {
  const server = await device.gatt?.connect()
  if (!server) throw new Error('Tidak dapat terhubung ke printer Bluetooth')

  try {
    const service = await server.getPrimaryService(PRINTER_SERVICE_UUID)
    const characteristic = await service.getCharacteristic(PRINTER_CHARACTERISTIC_UUID)

    for (let offset = 0; offset < bytes.length; offset += CHUNK_SIZE) {
      const chunk = bytes.slice(offset, offset + CHUNK_SIZE)
      await characteristic.writeValueWithoutResponse(chunk)
      await new Promise((resolve) => setTimeout(resolve, CHUNK_DELAY_MS))
    }
  } finally {
    server.disconnect()
  }
}

