import { EscPosBuilder } from '@adis/escpos'
import type { OrderTypeValue } from '@/lib/pos/cart-store'

export interface StationTicketItem {
  itemName: string
  variantName: string
  quantity: number
  notes?: string
}

export function buildStationTicket(params: {
  stationLabel: string
  orderNumber: string
  orderType: OrderTypeValue
  items: StationTicketItem[]
}): Uint8Array {
  const b = new EscPosBuilder().init().align('center').textSize(2, 2).bold(true)
  b.line(params.stationLabel)
  b.textSize(1, 1).bold(false)
  b.line(params.orderType === 'DINE_IN' ? 'DINE-IN' : 'TAKEAWAY')
  b.align('left').line('-'.repeat(32))
  b.line(`No: ${params.orderNumber}`)
  b.line('-'.repeat(32))

  b.textSize(2, 2).bold(true)
  for (const item of params.items) {
    b.line(`${item.quantity}x ${item.itemName}`)
    if (item.variantName) b.textSize(1, 1).line(`  (${item.variantName})`).textSize(2, 2)
    if (item.notes) b.textSize(1, 1).line(`  * ${item.notes}`).textSize(2, 2)
  }
  b.textSize(1, 1).bold(false)
  b.feed(3).cut()

  return b.toBytes()
}

