export interface ReceiptLineItem {
  itemName: string
  variantName: string
  quantity: number
  lineTotal: number
}

function formatRp(n: number) {
  return 'Rp' + Math.round(n).toLocaleString('id-ID')
}

function money(label: string, amount: number, width = 32) {
  const right = formatRp(amount)
  const gap = Math.max(1, width - label.length - right.length)
  return label + ' '.repeat(gap) + right
}

export function buildCustomerReceipt(params: {
  storeName: string
  addressLine?: string | null
  footerText?: string | null
  orderNumber: string
  createdAt: string
  orderType: OrderTypeValue
  paymentMethod: 'CASH' | 'QRIS'
  items: ReceiptLineItem[]
  subtotal: number
  taxAmount: number
  totalAmount: number
}): Uint8Array {
  const b = new EscPosBuilder().init().align('center').bold(true).line(params.storeName).bold(false)
  if (params.addressLine) b.line(params.addressLine)
  b.align('left').line('-'.repeat(32))
  b.line(`No: ${params.orderNumber}`)
  b.line(new Date(params.createdAt).toLocaleString('id-ID'))
  b.line(`${params.orderType === 'DINE_IN' ? 'Dine-in' : 'Takeaway'} - ${params.paymentMethod}`)
  b.line('-'.repeat(32))

  for (const item of params.items) {
    const name = `${item.quantity}x ${item.itemName}${item.variantName ? ` (${item.variantName})` : ''}`
    b.line(name)
    b.line(money('', item.lineTotal))
  }
  b.line('-'.repeat(32))
  b.line(money('Subtotal', params.subtotal))
  b.line(money('Pajak', params.taxAmount))
  b.bold(true).line(money('Total', params.totalAmount)).bold(false)

  if (params.footerText) {
    b.line('-'.repeat(32))
    b.align('center').line(params.footerText)
  }

  b.feed(3).cut()
  return b.toBytes()
}

