'use client'

import { useEffect, useState } from 'react'
import { Bluetooth } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  isBluetoothSupported,
  getRememberedPrinter,
  pairPrinter,
  printViaBluetooth,
} from '@/lib/print/bluetooth-client'
import { buildCustomerReceipt, type ReceiptLineItem } from '@/lib/print/receipt-templates'
import type { OrderTypeValue } from '@/lib/pos/cart-store'

interface BluetoothPrintButtonProps {
  storeName: string
  addressLine?: string | null
  footerText?: string | null
  orderNumber: string
  createdAt: string
  orderType: OrderTypeValue
  paymentMethod: 'CASH' | 'QRIS'
  items: ReceiptLineItem[]
  subtotal: number
  taxAmount: number
  totalAmount: number
}

export function BluetoothPrintButton(props: BluetoothPrintButtonProps) {
  const [device, setDevice] = useState<BluetoothDevice | null>(null)
  const [status, setStatus] = useState<string | null>(null)
  const [isBusy, setIsBusy] = useState(false)

  useEffect(() => {
    if (!isBluetoothSupported()) return
    getRememberedPrinter().then(setDevice)
  }, [])

  if (!isBluetoothSupported()) return null

  async function handlePrint() {
    setIsBusy(true)
    setStatus(null)
    try {
      const target = device ?? (await pairPrinter())
      if (!device) setDevice(target)

      const bytes = buildCustomerReceipt(props)
      await printViaBluetooth(target, bytes)
      setStatus('Struk terkirim ke printer.')
    } catch (e) {
      setStatus(e instanceof Error ? e.message : 'Gagal mencetak via Bluetooth')
    } finally {
      setIsBusy(false)
    }
  }

  return (
    <div className="no-print space-y-1">
      <Button variant="outline" onClick={handlePrint} disabled={isBusy} className="w-full gap-2">
        <Bluetooth className="size-4" />
        {isBusy ? 'Mencetak...' : device ? 'Cetak Struk (Bluetooth)' : 'Pasangkan & Cetak (Bluetooth)'}
      </Button>
      {status ? <p className="text-sm text-muted-foreground">{status}</p> : null}
    </div>
  )
}

