import { notFound } from 'next/navigation'
import Link from 'next/link'
import { createClient } from '@/lib/supabase/server'
import { Button } from '@/components/ui/button'
import { PrintButton } from '@/components/pos/print-button'
import { StationPrintButtons } from '@/components/pos/station-print-buttons'

function formatRp(n: number) {
  return 'Rp' + Math.round(n).toLocaleString('id-ID')
}

export default async function ReceiptPage({
  params,
}: {
  params: Promise<{ orderId: string }>
}) {
  const { orderId } = await params
  const supabase = await createClient()

  const { data: order } = await supabase.from('orders').select('*').eq('id', orderId).single()
  if (!order) notFound()

  const [{ data: items }, { data: settings }] = await Promise.all([
    supabase.from('order_items').select('*').eq('order_id', orderId).order('created_at'),
    supabase.from('receipt_settings').select('*').eq('branch_id', order.branch_id).maybeSingle(),
  ])

  const paperClass = settings?.paper_size === '58MM' ? 'paper-58mm' : 'paper-80mm'

  return (
    <div className="mx-auto max-w-sm space-y-4 p-4">
      <div className="no-print flex items-center justify-between">
        <Button variant="outline" render={<Link href="/pos" />}>
          Kembali ke POS
        </Button>
        <PrintButton />
      </div>

      <StationPrintButtons
        branchId={order.branch_id}
        orderId={order.id}
        orderNumber={order.order_number}
        orderType={order.order_type}
      />

      <div className={`receipt-print ${paperClass} mx-auto border p-3`}>
        <div className="text-center">
          <p className="font-bold">{settings?.store_name ?? 'Adi\'s Culinary'}</p>
          {settings?.address_line ? <p>{settings.address_line}</p> : null}
        </div>
        <hr className="my-2 border-dashed" />
        <div>
          <p>No: {order.order_number}</p>
          <p>{new Date(order.created_at).toLocaleString('id-ID')}</p>
          <p>{order.order_type === 'DINE_IN' ? 'Dine-in' : 'Takeaway'} · {order.payment_method}</p>
        </div>
        <hr className="my-2 border-dashed" />
        <div className="space-y-1">
          {items?.map((item) => (
            <div key={item.id} className="flex justify-between gap-2">
              <span>
                {item.quantity}x {item.item_name}
                {item.variant_name ? ` (${item.variant_name})` : ''}
              </span>
              <span>{formatRp(item.line_total)}</span>
            </div>
          ))}
        </div>
        <hr className="my-2 border-dashed" />
        <div className="space-y-1">
          <div className="flex justify-between">
            <span>Subtotal</span>
            <span>{formatRp(order.subtotal)}</span>
          </div>
          <div className="flex justify-between">
            <span>Pajak</span>
            <span>{formatRp(order.tax_amount)}</span>
          </div>
          <div className="flex justify-between font-bold">
            <span>Total</span>
            <span>{formatRp(order.total_amount)}</span>
          </div>
        </div>
        {settings?.footer_text ? (
          <>
            <hr className="my-2 border-dashed" />
            <p className="text-center">{settings.footer_text}</p>
          </>
        ) : null}
      </div>
    </div>
  )
}

