import { createClient } from '@/lib/supabase/server'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'

function formatRp(n: number) {
  return 'Rp' + Math.round(n).toLocaleString('id-ID')
}

export default async function PublicMenuPage() {
  const supabase = await createClient()
  const [{ data: categories }, { data: items }, { data: variants }] = await Promise.all([
    supabase.from('categories').select('id, name, sort_order').eq('is_active', true).order('sort_order'),
    supabase.from('menu_items').select('id, category_id, name, description').eq('is_active', true).order('sort_order'),
    supabase
      .from('menu_item_variants')
      .select('menu_item_id, name, price')
      .eq('is_active', true)
      .order('sort_order'),
  ])

  const variantsByItem = new Map<string, { name: string; price: number }[]>()
  for (const v of variants ?? []) {
    const list = variantsByItem.get(v.menu_item_id) ?? []
    list.push({ name: v.name, price: v.price })
    variantsByItem.set(v.menu_item_id, list)
  }

  const itemsByCategory = new Map<string, typeof items>()
  for (const item of items ?? []) {
    const list = itemsByCategory.get(item.category_id) ?? []
    list.push(item)
    itemsByCategory.set(item.category_id, list)
  }

  return (
    <div className="space-y-8 py-8">
      <h1 className="text-2xl font-bold">Menu</h1>
      {categories?.map((category) => {
        const categoryItems = (itemsByCategory.get(category.id) ?? []).filter(
          (i) => (variantsByItem.get(i.id) ?? []).length > 0
        )
        if (!categoryItems.length) return null
        return (
          <section key={category.id} className="space-y-3">
            <h2 className="text-lg font-semibold">{category.name}</h2>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {categoryItems.map((item) => {
                const itemVariants = variantsByItem.get(item.id) ?? []
                return (
                  <Card key={item.id}>
                    <CardHeader>
                      <CardTitle className="text-base">{item.name}</CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-1 text-sm">
                      {item.description ? (
                        <p className="text-muted-foreground">{item.description}</p>
                      ) : null}
                      {itemVariants.map((v) => (
                        <div key={v.name} className="flex justify-between">
                          <span>{v.name}</span>
                          <span className="font-medium">{formatRp(v.price)}</span>
                        </div>
                      ))}
                    </CardContent>
                  </Card>
                )
              })}
            </div>
          </section>
        )
      })}
    </div>
  )
}

