              {b.phone ? (
                <p className="flex items-center gap-2">
                  <Phone className="size-4 shrink-0" />
                  {b.phone}
                </p>
              ) : null}
            </CardContent>
          </Card>
        ))}
        {!branches?.length ? (
          <p className="text-sm text-muted-foreground">Belum ada cabang yang terdaftar.</p>
        ) : null}
      </div>
    </div>
  )
}

