1	-- Atomic order creation. Runs security invoker so RLS still applies per-caller —
2	-- a cashier cannot be tricked into cross-branch inserts even through this function.
3	-- print_station is resolved here from menu_items/categories, never trusted from the client.
4	
5	create or replace function create_order(
6	  p_branch_id uuid,
7	  p_order_type order_type,
8	  p_payment_method payment_method,
9	  p_items jsonb,       -- [{menu_item_id, variant_id, quantity, notes}, ...]
10	  p_notes text default null
11	) returns uuid
12	language plpgsql security invoker as $$
13	declare
14	  v_order_id uuid;
15	  v_item jsonb;
16	  v_variant record;
17	  v_subtotal numeric(12,2) := 0;
18	  v_tax_rate numeric(5,4);
19	  v_line_total numeric(12,2);
20	  v_item_count int := 0;
21	begin
22	  if p_branch_id <> auth_branch_id() and not is_super_admin() then
23	    raise exception 'branch mismatch';
24	  end if;
25	
26	  if jsonb_array_length(p_items) = 0 then
27	    raise exception 'order must contain at least one item';
28	  end if;
29	
30	  select coalesce(tax_rate, 0) into v_tax_rate
31	  from receipt_settings where branch_id = p_branch_id;
32	
33	  insert into orders (branch_id, cashier_id, order_number, order_type, payment_method, notes)
34	  values (p_branch_id, auth.uid(), 'TEMP', p_order_type, p_payment_method, p_notes)
35	  returning id into v_order_id;
36	
37	  for v_item in select * from jsonb_array_elements(p_items) loop
38	    select miv.price, mi.name as item_name, miv.name as variant_name,
39	           coalesce(mi.print_station, c.default_print_station) as print_station
40	      into v_variant
41	      from menu_item_variants miv
42	      join menu_items mi on mi.id = miv.menu_item_id
43	      join categories c on c.id = mi.category_id
44	      where miv.id = (v_item->>'variant_id')::uuid
45	        and mi.id = (v_item->>'menu_item_id')::uuid
46	        and miv.is_active and mi.is_active;
47	
48	    if not found then
49	      raise exception 'invalid or inactive menu item/variant: %', v_item;
50	    end if;
51	
52	    v_line_total := v_variant.price * (v_item->>'quantity')::int;
53	    v_subtotal := v_subtotal + v_line_total;
54	    v_item_count := v_item_count + 1;
55	
56	    insert into order_items (
57	      order_id, branch_id, menu_item_id, variant_id, item_name, variant_name,
58	      unit_price, quantity, line_total, print_station, notes
59	    )
60	    values (
61	      v_order_id, p_branch_id, (v_item->>'menu_item_id')::uuid, (v_item->>'variant_id')::uuid,
62	      v_variant.item_name, v_variant.variant_name, v_variant.price,
63	      (v_item->>'quantity')::int, v_line_total, v_variant.print_station,
64	      v_item->>'notes'
65	    );
66	  end loop;
67	
68	  update orders set
69	    order_number = 'ORD-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(nextval('order_seq')::text, 4, '0'),
70	    subtotal = v_subtotal,
71	    tax_amount = round(v_subtotal * v_tax_rate, 2),
72	    total_amount = v_subtotal + round(v_subtotal * v_tax_rate, 2)
73	  where id = v_order_id;
74	
75	  return v_order_id;
76	end;
77	$$;
78	
79	revoke execute on function create_order(uuid, order_type, payment_method, jsonb, text) from public;
80	grant execute on function create_order(uuid, order_type, payment_method, jsonb, text) to authenticated;
81	
