'use server'

import { revalidatePath } from 'next/cache'
import { createClient } from '@/lib/supabase/server'
import { createAdminClient } from '@/lib/supabase/admin'
import type { UserRole } from '@/lib/supabase/types'

async function assertSuperAdmin() {
  const supabase = await createClient()
  const { data } = await supabase.auth.getClaims()
  if (data?.claims?.user_role !== 'SUPER_ADMIN') {
    throw new Error('Hanya Super Admin yang dapat mengelola pengguna')
  }
}

export async function createUser(formData: FormData) {
  await assertSuperAdmin()

  const fullName = String(formData.get('full_name') ?? '').trim()
  const email = String(formData.get('email') ?? '').trim()
  const password = String(formData.get('password') ?? '')
  const role = String(formData.get('role') ?? '') as UserRole
  const branchId = String(formData.get('branch_id') ?? '') || null

  if (!fullName || !email || !password) throw new Error('Semua field wajib diisi')
  if (role !== 'SUPER_ADMIN' && role !== 'CASHIER') throw new Error('Role tidak valid')
  if (role === 'CASHIER' && !branchId) throw new Error('Kasir wajib memiliki cabang')
  if (password.length < 8) throw new Error('Password minimal 8 karakter')

  const admin = createAdminClient()

  const { data: created, error: createError } = await admin.auth.admin.createUser({
    email,
    password,
    email_confirm: true,
  })
  if (createError || !created.user) {
    throw new Error(createError?.message ?? 'Gagal membuat akun')
  }

  const { error: profileError } = await admin.from('profiles').insert({
    id: created.user.id,
    full_name: fullName,
    role,
    branch_id: role === 'CASHIER' ? branchId : null,
  })
  if (profileError) {
    // Roll back the auth user so we don't leave an orphaned account with no profile.
    await admin.auth.admin.deleteUser(created.user.id)
    throw new Error(profileError.message)
  }

  revalidatePath('/admin/users')
}

export async function setUserActive(id: string, isActive: boolean) {
  await assertSuperAdmin()
  const admin = createAdminClient()
  const { error } = await admin.from('profiles').update({ is_active: isActive }).eq('id', id)
  if (error) throw new Error(error.message)
  revalidatePath('/admin/users')
}

